interface SurahViewProps {
  verses: any[];
  surahId?: string;
  pageMap?: { [key: string]: number };
  showBismillah?: boolean;
}

// Page break indicator component
function PageBreak({ pageNumber }: { pageNumber: number }) {
  return (
    <div dir="ltr" className="w-full flex items-center justify-center my-8 select-none">
      <div className="flex items-center gap-4 px-6 py-2 rounded-full bg-gray-800/30 border border-gray-700/50">
        <div className="w-8 h-px bg-gradient-to-r from-transparent to-gray-600" />
        <div className="flex items-center gap-2">
          <svg className="w-4 h-4 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          <span className="text-xs font-english text-gray-500">
            Page <span className="text-emerald-500 font-semibold">{pageNumber}</span>
          </span>
        </div>
        <div className="w-8 h-px bg-gradient-to-l from-transparent to-gray-600" />
      </div>
    </div>
  );
}

